ROOT = Path(__file__).resolve().parents[1]

def brl(value):
    return 'R$ ' + f'{Decimal(value):,.2f}'.replace(',', '_').replace('.', ',').replace('_', '.')

def integer(value):
    return f'{value:,}'.replace(',', '.')

def table(headers, rows, caption=''):
    return '<div class="table-wrap"><table>' + (f'<caption>{caption}</caption>' if caption else '') + '<thead><tr>' + ''.join(f'<th scope="col">{x}</th>' for x in headers) + '</tr></thead><tbody>' + ''.join('<tr>' + ''.join(f'<td>{x}</td>' for x in row) + '</tr>' for row in rows) + '</tbody></table></div>'

