mdr = checkout_types['VENDA']['fee'] + checkout_types['ESTORNO']['fee']
advance = checkout_types['ANTECIPACAO']['fee'] + checkout_types['REVERSAO ANTECIPACAO']['fee']
matched_differences = [r for r in a.comparisons if r['contract_pct'] != r['taxa_aplicada_pct']]
