portfolio = []
for ec in sorted({r['cod_estabelecimento'] for r in a.checkout}):
    rows = [r for r in a.checkout if r['cod_estabelecimento'] == ec]
    portfolio.append({'ec': ec, 'name': rows[0]['nome_estabelecimento'], 'count': len(rows), 'fee': a.total(rows,'valor_taxa'), 'mapped': bool(a.by_ec[ec])})
portfolio.sort(key=lambda r: r['fee'], reverse=True)

type_rows = []
for key in ['VENDA','ESTORNO','ANTECIPACAO','REVERSAO ANTECIPACAO']:
    row = checkout_types[key]
    type_rows.append([key.replace('ANTECIPACAO','ANTECIPAÇÃO').replace('REVERSAO','REVERSÃO'), integer(row['count']), brl(row['gross']), brl(row['fee'])])
type_rows.append(['<strong>Total algébrico do arquivo</strong>', '<strong>1.943</strong>', '<strong>'+brl(a.total(a.checkout,'valor_bruto'))+'</strong>', '<strong>'+brl(a.total(a.checkout,'valor_taxa'))+'</strong>'])

